import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Profile = ({ onModuleChange }) => {
  const [user, setUser] = useState({ name: '', email: '' });
  const [editMode, setEditMode] = useState(false);
  const [form, setForm] = useState({ name: '', email: '' });
  const [message, setMessage] = useState('');
  const [savedRecipes, setSavedRecipes] = useState([]);
  const [loadingRecipe, setLoadingRecipe] = useState(null);
  const navigate = useNavigate();

  // Only call onModuleChange('profile') on mount
  useEffect(() => {
    if (onModuleChange) onModuleChange('profile');
    // Fetch details of the currently signed-in user
    const token = localStorage.getItem('token');
    if (!token) return;
    fetch('http://localhost:5000/api/users/me', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => {
        setUser({ name: data.name, email: data.email });
        setForm({ name: data.name, email: data.email });
      })
      .catch(() => setMessage('Failed to fetch user details'));

    // Fetch saved recipes for the user
    fetch('http://localhost:5000/api/users/saved-recipes', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setSavedRecipes(data))
      .catch(() => setSavedRecipes([]));
    // eslint-disable-next-line
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleEdit = () => {
    setEditMode(true);
    setMessage('');
  };

  const handleCancel = () => {
    setEditMode(false);
    setForm({ name: user.name, email: user.email });
    setMessage('');
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setMessage('');
    const token = localStorage.getItem('token');
    try {
      const res = await fetch('http://localhost:5000/api/users/update', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      if (!res.ok) {
        setMessage(data.message || 'Failed to update');
        return;
      }
      setUser({ name: data.name, email: data.email });
      setEditMode(false);
      setMessage('Profile updated successfully!');
    } catch {
      setMessage('Server error');
    }
  };

  // Fetch full recipe details from backend (by _id or dish_name)
  const handleRecipeSelected = async (recipe) => {
    setLoadingRecipe(recipe._id || recipe.id || recipe.dish_name || recipe.name);
    let recipeDetails = null;
    try {
      // Prefer _id, fallback to dish_name
      if (recipe._id || recipe.id) {
        const res = await fetch(`http://localhost:8000/recipe/${recipe._id || recipe.id}`);
        recipeDetails = await res.json();
      } else if (recipe.dish_name) {
        // fallback: search by dish name
        const res = await fetch('http://localhost:8000/get_recipe', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query: recipe.dish_name })
        });
        recipeDetails = await res.json();
      }
      if (recipeDetails) {
        localStorage.setItem('selectedRecipe', JSON.stringify(recipeDetails));
        setLoadingRecipe(null);
        navigate('/results', { state: { recipe: recipeDetails } });
      }
    } catch {
      setLoadingRecipe(null);
      alert('Failed to fetch recipe details.');
    }
  };

  return (
    <section className="container" style={{ maxWidth: 600, margin: '60px auto' }}>
      <div className="card">
        <h2 style={{ textAlign: 'center', marginBottom: 24 }}>Profile</h2>
        {editMode ? (
          <form onSubmit={handleSave}>
            <div className="form-group">
              <label className="form-label">Name</label>
              <input
                className="form-input"
                type="text"
                name="name"
                value={form.name}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label">Email</label>
              <input
                className="form-input"
                type="email"
                name="email"
                value={form.email}
                onChange={handleChange}
                required
              />
            </div>
            {message && (
              <div style={{ color: message.includes('success') ? 'green' : 'red', textAlign: 'center', marginBottom: 12 }}>
                {message}
              </div>
            )}
            <button className="btn btn-primary w-full" type="submit">Save</button>
            <button className="btn btn-secondary w-full" type="button" style={{ marginTop: 8 }} onClick={handleCancel}>Cancel</button>
          </form>
        ) : (
          <>
            <div style={{ marginBottom: 16 }}>
              <strong>Name:</strong> <span>{user.name}</span>
            </div>
            <div style={{ marginBottom: 16 }}>
              <strong>Email:</strong> <span>{user.email}</span>
            </div>
            {message && (
              <div style={{ color: 'red', textAlign: 'center', marginBottom: 12 }}>
                {message}
              </div>
            )}
            <button className="btn btn-primary w-full" onClick={handleEdit}>Edit</button>
            {/* Saved Recipes Section */}
            <div style={{ marginTop: 32 }}>
              <h3 style={{ marginBottom: 12 }}>❤️ Saved Recipes</h3>
              {savedRecipes.length === 0 ? (
                <div style={{ color: '#999', fontSize: 15 }}>No saved recipes yet.</div>
              ) : (
                <div className="saved-recipes-grid" style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))',
                  gap: '18px'
                }}>
                  {savedRecipes.map((item, idx) => {
                    const recipe = item.recipe || {};
                    return (
                      <div key={item._id || idx} className="saved-recipe-card card" style={{
                        padding: 18,
                        borderRadius: 12,
                        boxShadow: '0 2px 8px #e3eaff',
                        background: '#fff'
                      }}>
                        <div style={{ fontWeight: 700, fontSize: 18, color: '#764ba2', marginBottom: 6 }}>
                          {recipe.dish_name || recipe.name || 'Recipe'}
                        </div>
                        <div style={{ color: '#667eea', fontSize: 15, marginBottom: 4 }}>
                          <span style={{ marginRight: 12 }}>
                            <strong>Cuisine:</strong> {recipe.cuisine || 'N/A'}
                          </span>
                          <span>
                            <strong>Servings:</strong> {recipe.servings_scaled_to || recipe.servings || 'N/A'}
                          </span>
                        </div>
                        <div style={{ color: '#333', fontSize: 14, marginBottom: 8 }}>
                          <strong>Type:</strong> {recipe.type || 'N/A'}
                        </div>
                        <button
                          className="btn btn-primary"
                          style={{ marginTop: 8, width: '100%' }}
                          onClick={() => handleRecipeSelected(recipe)}
                          disabled={loadingRecipe === (recipe._id || recipe.id || recipe.dish_name || recipe.name)}
                        >
                          {loadingRecipe === (recipe._id || recipe.id || recipe.dish_name || recipe.name)
                            ? 'Loading...'
                            : 'View Details'}
                        </button>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </>
        )}
      </div>
    </section>
  );
};

export default Profile;
